var DIAGRAMME = (function(){
  var n = 0;
  MODULES.forEach(function(m){ m.lessons.forEach(function(l){
    n += (String(l.body || "").match(/<figure class="fig">/g) || []).length;
  }); });
  return n;
})();
function today0(){ var d = new Date(); d.setHours(0,0,0,0); return d.getTime(); }

