    state.completed = new Set();
    state.srs = {}; state.stats = {}; state.exams = [];
    state.xp = 0; state.xpLog = {}; state.badges = {}; state.solved = {};
    state.tracesDone = []; state.streak = { last:null, count:0, best:0 };
    state.cardsToday = { day:null, n:0 };
